"""Build the publication-safe static site from canonical public tables.

The script reads only tracked, sanitized CSV files under ``results/tables``.
It never reads private run directories or checkpoints.
"""
from __future__ import annotations

import csv
import statistics
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"
PROJECT = DOCS / "projects" / "01-quadratic-gpt2"
REPO = "https://github.com/xxlilloxx-cyber/federico-lolli-ai-research"


def rows(path: str) -> list[dict[str, str]]:
    with (ROOT / path).open(newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def shell(title: str, current: str, body: str, description: str = "") -> str:
    items = [
        ("Overview", "index.html", "overview"),
        ("Method", "method.html", "method"),
        ("Experiments", "experiments.html", "experiments"),
        ("Results", "results.html", "results"),
        ("Mechanism", "mechanism.html", "mechanism"),
        ("Comparisons", "comparisons.html", "comparisons"),
        ("Conclusions", "conclusions.html", "conclusions"),
        ("Reproducibility", "reproducibility.html", "reproducibility"),
        ("References", "references.html", "references"),
    ]
    nav = "".join(
        f'<a{(" aria-current=\"page\"" if key == current else "")} href="{href}">{label}</a>'
        for label, href, key in items
    )
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{description}"><title>{title}</title><link rel="stylesheet" href="../../assets/site.css"></head><body>
<header class="site-header"><nav class="nav" aria-label="Site navigation"><a class="brand" href="../../index.html">Federico Lolli<small>AI Research</small></a><div class="nav-links"><a href="../../research/index.html">Projects</a><a href="../../about.html">About</a></div></nav></header><nav class="project-nav" aria-label="Project 01 navigation"><div class="inner">{nav}</div></nav>
<main>{body}</main><footer class="site-footer"><p>Project 01 · Federico Lolli · <a href="mailto:xxlilloxx@gmail.com">xxlilloxx@gmail.com</a></p><p>Original code: <a href="{REPO}/blob/main/LICENSE">MIT</a>. Original text and figures: <a href="{REPO}/blob/main/LICENSE-CONTENT.md">CC BY 4.0</a>. Third-party materials retain their own terms.</p></footer></body></html>'''


def table(headers: list[str], data: list[list[str]], caption: str) -> str:
    head = "".join(f"<th>{x}</th>" for x in headers)
    body = "".join("<tr>" + "".join(f"<td>{x}</td>" for x in row) + "</tr>" for row in data)
    return f'<div class="table-wrap"><table><caption>{caption}</caption><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'


def figure(src: str, alt: str, caption: str) -> str:
    return f'<figure class="figure"><img src="../../assets/{src}" alt="{alt}"><figcaption>{caption}</figcaption></figure>'


def project_pages() -> dict[str, str]:
    rank = rows("results/tables/rank-confirmation-5000/rank_5000_aggregate.csv")
    ag = rows("results/tables/downstream-ag-news/downstream_controlled_aggregate.csv")
    scaling = rows("results/tables/scaling-ablation/rank_scaling_ablation_aggregate.csv")
    paired = rows("results/tables/rank-confirmation-5000/rank_5000_paired_differences.csv")
    convergence = rows("results/tables/rank-confirmation-5000/rank_5000_convergence.csv")
    cost = rows("results/tables/computational-cost/computational_cost.csv")
    rank_table = []
    for r in (1, 2, 4, 8):
        l = next(x for x in rank if x["method"] == "LoRA" and int(x["rank"]) == r)
        s = next(x for x in rank if x["method"] == "Symmetric Quadratic" and int(x["rank"]) == r)
        rank_table.append([str(r), f'{float(l["final_validation_loss_mean"]):.4f} ± {float(l["final_validation_loss_sample_sd"]):.4f}', f'{float(s["final_validation_loss_mean"]):.4f} ± {float(s["final_validation_loss_sample_sd"]):.4f}', f'{float(l["final_test_loss_mean"]):.4f} ± {float(l["final_test_loss_sample_sd"]):.4f}', f'{float(s["final_test_loss_mean"]):.4f} ± {float(s["final_test_loss_sample_sd"]):.4f}'])
    ag_table = [["LoRA", f'{float(ag[0]["test_accuracy_mean"]):.4f} ± {float(ag[0]["test_accuracy_sample_sd"]):.4f}', f'{float(ag[0]["test_macro_f1_mean"]):.4f} ± {float(ag[0]["test_macro_f1_sample_sd"]):.4f}', f'{float(ag[0]["test_loss_mean"]):.4f} ± {float(ag[0]["test_loss_sample_sd"]):.4f}'], ["Symmetric Quadratic", f'{float(ag[1]["test_accuracy_mean"]):.4f} ± {float(ag[1]["test_accuracy_sample_sd"]):.4f}', f'{float(ag[1]["test_macro_f1_mean"]):.4f} ± {float(ag[1]["test_macro_f1_sample_sd"]):.4f}', f'{float(ag[1]["test_loss_mean"]):.4f} ± {float(ag[1]["test_loss_sample_sd"]):.4f}']]
    paired_table = []
    for r in (1, 2, 4, 8):
        values = [float(x["symmetric_minus_lora_final_test_loss"]) for x in paired if int(x["rank"]) == r]
        paired_table.append([str(r), f'{statistics.mean(values):.4f} ± {statistics.stdev(values):.4f}', f'{sum(v < 0 for v in values)}/3'])
    scaling_table = []
    for r in (1, 2, 4, 8):
        row = [str(r)]
        for policy in ("current_alpha_4", "constant_effective_scale"):
            l = next(x for x in scaling if x["policy"] == policy and x["method"] == "LoRA" and int(x["rank"]) == r)
            s = next(x for x in scaling if x["policy"] == policy and x["method"] == "Symmetric Quadratic" and int(x["rank"]) == r)
            row.extend([f'{float(l["final_validation_loss"]):.4f}', f'{float(s["final_validation_loss"]):.4f}', f'{float(s["final_validation_loss"]) - float(l["final_validation_loss"]):+.4f}'])
        scaling_table.append(row)
    convergence_table = []
    for r in (1, 2, 4, 8):
        row = [str(r)]
        for step in (1000, 2000, 3000, 4000, 5000):
            l = [float(x["validation_loss"]) for x in convergence if x["method"] == "LoRA" and int(x["rank"]) == r and int(x["step"]) == step]
            s = [float(x["validation_loss"]) for x in convergence if x["method"] == "Symmetric Quadratic" and int(x["rank"]) == r and int(x["step"]) == step]
            row.append(f'{statistics.mean(b - a for a, b in zip(l, s)):+.4f}')
        convergence_table.append(row)
    overview = '''<section class="hero"><p class="eyebrow">Research Project 01 · Exploratory controlled study</p><h1>Symmetric Quadratic Adaptation</h1><p class="lede">Can structured quadratic interactions improve the expressive efficiency of low-rank Transformer adaptation under controlled parameter budgets?</p><p>The project keeps GPT-2 frozen and trains small corrections beside selected projections. It compares the linear LoRA baseline with an activation-dependent quadratic branch, then tests rank, placement, training duration, task transfer, scaling, derivatives, and cost.</p><div class="formula">LoRA: Δy = (α/r)(xA)B<br>Symmetric: Δy = (α/r)((xU) ⊙ (xU))P</div><div class="callout good"><strong>Key evidence.</strong><br>WikiText-2, 5,000 steps, rank-8 held-out test: LoRA 3.7319 ± 0.0035; Symmetric 3.6938 ± 0.0044.<br>AG News accuracy: LoRA 0.8201 ± 0.0051; Symmetric 0.8021 ± 0.0240.<br><strong>The observed advantage is task dependent.</strong></div></section>''' + figure("publication/adapter_architecture_comparison.svg", "Matched LoRA and Symmetric Quadratic branches running in parallel with a frozen row-vector projection. LoRA applies xA then B; Symmetric applies xU, the element-wise square z times z, then P.", "<strong>Figure 1.</strong> Architecture of the matched LoRA and Symmetric Quadratic adapters. Both add a low-rank trainable branch beside the frozen projection. LoRA applies two linear projections, whereas Symmetric inserts an element-wise square of the projected activation before the output projection, producing an activation-dependent quadratic correction.") + '''<section><h2>Evidence at a glance</h2><div class="grid"><article class="card"><h3>Language modelling</h3><p>24 fresh 5,000-step runs: 2 methods × 4 ranks × 3 seeds on WikiText-2.</p></article><article class="card"><h3>Downstream classification</h3><p>Six matched AG News runs, reporting held-out accuracy and macro-F1.</p></article><article class="card"><h3>Mechanism and cost</h3><p>Local Jacobian spectra, adapter Hessians, convergence, and matched rank-4 latency/VRAM.</p></article></div><p><a href="results.html">Read the results</a> · <a href="../../data/TECHNICAL_REPORT.md">Extended technical report</a> · <a href="../../data/SCIENTIFIC_MANUSCRIPT.md">Scientific manuscript</a></p></section>'''
    method = '''<section class="hero compact"><p class="eyebrow">Project 01 · Method</p><h1>Linear and quadratic low-rank corrections</h1><p class="lede">The adapter is a trainable correction added beside a frozen GPT-2 projection rather than a replacement for the pretrained model. The backbone weights remain fixed, and only a small low-rank branch is optimized.</p><p>This isolates the effect of changing the adapter’s functional form while keeping its trainable parameter budget controlled. LoRA is the direct linear baseline. Symmetric uses the same low-rank matrix shapes but inserts an element-wise square between the first projection and the output projection, producing an activation-dependent quadratic correction rather than a fixed linear update.</p></section><section><h2>Notation</h2><p>For row activation <code>x ∈ R^(1×d)</code>, frozen projection <code>W ∈ R^(d×d_out)</code>, and frozen bias <code>b</code>, the pretrained projection is:</p><div class="formula">y_base = xW + b</div><p>The trainable adapter output is added to this frozen projection:</p><div class="formula">Δy_LoRA = (α/r)(xA)B<br>Δy_Symmetric = (α/r)((xU) ⊙ (xU))P</div><p>Here <code>A,U ∈ R^(d×r)</code> and <code>B,P ∈ R^(r×d_out)</code>. Both adapters therefore use two trainable low-rank matrices with matched shapes and parameter count <code>r(d+d_out)</code>. LoRA performs two linear projections. Symmetric performs the first low-rank projection, squares the projected activation element by element, and then applies the output projection.</p><p>In the controlled rank study, α=4, giving α/r values 4, 2, 1, and 0.5 at ranks 1, 2, 4, and 8. This changing effective scale motivated the separate constant-scale ablation.</p><h2>Quadratic structure</h2><div class="formula">Δy_j = (α/r) Σ_k P_kj (xu_k)² = xQ_jxᵀ<br>Q_j = (α/r) U diag(P[:,j]) Uᵀ</div><p>Each output coordinate therefore corresponds to a symmetric factorized quadratic form. Projection directions in <code>U</code> are shared across output coordinates, while <code>P</code> supplies output-specific signed coefficients. Because those coefficients may be positive or negative, an individual <code>Q_j</code> need not be positive semidefinite.</p><div class="formula">(ax₁+bx₂)² = a²x₁² + 2abx₁x₂ + b²x₂²</div><p>The square of a projected activation is therefore not limited to independent squared features: it introduces pairwise cross-terms between input dimensions. LoRA remains linear in the adapter input, whereas Symmetric introduces explicit second-order interactions.</p></section>''' + figure("figures/gpt2-attn-adapter-path.svg", "GPT-2 block with the adapter parallel to the frozen attention output projection, followed by residual dropout and residual addition.", "<strong>Figure 2.</strong> Placement of the low-rank adapter in the controlled GPT-2 experiments. The adapter receives the same input as the frozen attention <code>c_proj</code> projection. The frozen projection output and adapter correction are summed before attention residual dropout and the residual addition. Transformer block indices are zero based.")
    experiments = '''<section class="hero compact"><p class="eyebrow">Project 01 · Experiments</p><h1>Experiments by protocol</h1><p class="lede">The research was conducted in two broad stages. Exploratory studies identified promising questions; controlled campaigns then tested them with matched budgets, fixed placement, repeated seeds, and separate validation and held-out test evaluation.</p><p>The historical experiments explain how the research direction emerged, while the controlled campaigns provide the main quantitative evidence used in the conclusions.</p></section><section><h2>Completed campaigns</h2>''' + table(["Campaign", "Design", "Role"], [["Historical adapter families", "LoRA, element-wise/signed quadratic, interaction, Symmetric, and Linear+Quadratic variants across 500, 1,000, and 2,000-step studies", "Exploratory architecture comparison"], ["Depth and placement", "Attention and MLP placement screens, including a full 12-block attention scan", "Placement exploration"], ["Fixed-budget multilayer", "Matched 6,144- and 12,288-parameter configurations distributed across multiple layers", "Depth versus local-rank analysis"], ["AG News", "LoRA and Symmetric, three seeds, 500 steps", "Controlled downstream classification"], ["Rank screening", "2 methods × 4 ranks × 3 seeds, 1,000 steps", "Controlled rank screening"], ["Rank confirmation", "24 independent fresh runs, 5,000 steps", "Central controlled language-modelling result"], ["Scaling ablation", "α=4 compared with constant α/r=1, seed 42", "Single-seed scaling-confound check"], ["Mechanism analysis", "Stored checkpoints evaluated through local Jacobians, effective-rank measures, and adapter-only Hessians", "Structural characterization"], ["Computational benchmark", "Matched rank-4 latency, backward time, throughput, and peak VRAM", "Practical cost comparison"]], "Completed experimental campaigns") + '''<h2>Historical exploration</h2><p>The early experiments were not designed as one uniform benchmark. They explored whether quadratic or interaction-based adapters were trainable, whether placement mattered, and whether distributing a fixed budget across layers changed performance. Their protocols differ, so their measurements remain separate from the controlled rank and downstream studies.</p><p><strong>Best recorded validation</strong>, <strong>final validation at a fixed step</strong>, and <strong>held-out final test</strong> are distinct quantities and are never merged.</p><h2>Controlled WikiText-2 protocol</h2><p>The central language-modelling experiments freeze GPT-2 Small and tokenize WikiText-2 into consecutive 128-token blocks for causal cross-entropy training. They adapt only zero-based Transformer block 0 <code>attn.c_proj</code> and use AdamW, learning rate 3×10⁻⁴, gradient accumulation 4, α=4, ranks 1/2/4/8, and seeds 42/123/456.</p><p>The 1,000-step screening and 5,000-step confirmation are independent experiments. The confirmation contains 2 methods × 4 ranks × 3 seeds = 24 fresh runs. The held-out test set is evaluated only from the final checkpoint and does not select method, rank, hyperparameters, or checkpoint.</p><h2>Controlled AG News protocol</h2><p>The downstream experiment uses the same frozen GPT-2 backbone and controlled adapter placement with a trainable classification head. It uses 4,096 training examples, a fixed 1,000-example stratified validation subset, the original AG News test set, LoRA and Symmetric, seeds 42/123/456, and 500 optimization steps. It tests transfer to classification rather than repeating language modelling.</p><h2>Why the protocol matters</h2><p>The controlled comparisons match backbone, placement, rank, trainable parameter count, optimizer, training budget, and seed set. Separate scaling, convergence, and AG News analyses isolate specific questions about effective scale, optimization duration, and task transfer. This design supports a measured interpretation involving parameter budget, rank, scaling, duration, and task rather than attributing every difference to the quadratic operation alone.</p></section>'''
    results = '''<section class="hero compact"><p class="eyebrow">Project 01 · Results</p><h1>Controlled evidence is task dependent</h1><p class="lede">The central evidence combines 24 fresh WikiText-2 confirmation runs with six matched AG News runs. Values are means ± sample SD over seeds 42, 123, and 456 unless explicitly identified as single-seed.</p><p>Lower loss is better; higher accuracy and macro-F1 are better. Validation and held-out test results are reported separately.</p></section><section><h2>5,000-step WikiText-2 confirmation</h2>''' + table(["Rank", "LoRA final val", "Symmetric final val", "LoRA test", "Symmetric test"], rank_table, "Fresh final-checkpoint loss; three seeds") + table(["Rank", "Paired test difference (Symmetric − LoRA)", "Seeds favouring Symmetric"], paired_table, "Within-seed held-out differences; negative favours Symmetric") + figure("publication/rank_5000_final_test_loss.svg", "Held-out test loss against rank for LoRA and Symmetric, with individual seed points and sample SD.", "<strong>Figure 3.</strong> Final held-out test loss in the independent 5,000-step confirmation. Symmetric has lower mean loss at every tested rank in this configuration; individual seeds and sample-SD uncertainty remain visible.") + '''<p>All twelve paired seed comparisons favour Symmetric on held-out loss. The largest mean paired test difference occurs at rank 8. This evidence is specific to the tested backbone, task, placement, schedule, and scaling policy.</p><h2>AG News classification</h2>''' + table(["Method", "Test accuracy", "Test macro-F1", "Test loss"], ag_table, "Held-out AG News results; three seeds") + figure("publication/downstream_accuracy_comparison.svg", "AG News test accuracy means, sample SD, and all individual seed observations.", "<strong>Figure 4.</strong> Controlled AG News held-out accuracy. LoRA is higher on average, and all seed observations remain visible.") + '''<p>AG News reverses the average ordering: LoRA has higher accuracy and macro-F1 and lower test loss. The classification result is direct evidence that the WikiText-2 advantage does not transfer automatically across tasks.</p><h2>Single-seed scaling ablation</h2>''' + table(["Rank", "LoRA α=4", "Sym α=4", "Δ", "LoRA α/r=1", "Sym α/r=1", "Δ"], scaling_table, "Final validation loss after 1,000 steps, seed 42 only") + '''<p>Constant effective scale changes the magnitude but preserves the tested seed’s sign pattern: LoRA is lower at rank 1, while Symmetric is lower at ranks 2, 4, and 8. Because this ablation contains only seed 42, it cannot support a broader population-level conclusion.</p>''' + figure("publication/rank_scaling_ablation_loss.svg", "Seed-42 validation loss by rank under fixed alpha and constant effective scale.", "<strong>Figure 5.</strong> Single-seed scaling ablation. Scaling changes effect magnitude and remains a qualification on the primary rank study.") + '''<h2>Convergence</h2>''' + table(["Rank", "Step 1,000", "2,000", "3,000", "4,000", "5,000"], convergence_table, "Mean paired validation difference (Symmetric − LoRA) in fresh confirmation trajectories") + '''<p>The independent 1,000-step screen is not concatenated with these 5,000-step trajectories. In the fresh confirmation, rank 1 changes from LoRA-favoured to Symmetric-favoured between the recorded 2,000- and 3,000-step checkpoints. Ranks 2, 4, and 8 favour Symmetric from the recorded 1,000-step point onward, while the gaps at ranks 4 and 8 narrow by step 5,000.</p>''' + figure("publication/convergence_rank1.svg", "Fresh rank-1 validation trajectories for LoRA and Symmetric through 5,000 optimizer steps.", "<strong>Figure 6.</strong> Rank-1 crossover within the independent confirmation campaign; bands show sample SD across the three seeds.") + '''<h2>Overall interpretation</h2><p>Under the controlled WikiText-2 configuration, Symmetric achieves lower final validation and held-out test loss at every tested rank. Under the controlled AG News configuration, LoRA performs better on average. Scaling and convergence results further show that effective scale and optimization duration affect the comparison. Together, the evidence supports a task-dependent alternative rather than a universal replacement for LoRA.</p></section>'''
    mechanism = '''<section class="hero compact"><p class="eyebrow">Project 01 · Mechanism</p><h1>Derivatives and learned spectra</h1><p class="lede">The analyses in this section characterize the local behavior of the trained adapters. They establish structural differences between LoRA and Symmetric Quadratic Adaptation, but they do not by themselves explain the observed performance differences.</p></section><section><h2>Local Jacobians</h2><div class="formula">J<sub>LoRA</sub> = (α/r)AB<br>J<sub>Symmetric</sub>(x) = 2(α/r) U diag(xU) P</div><p>LoRA is linear at the adapter level, so its Jacobian is independent of the input activation. Its local transformation can therefore be represented by one fixed low-rank update matrix. The Symmetric adapter is quadratic. Its Jacobian depends explicitly on the current activation through <code>diag(xU)</code>, so the effective local transformation changes with the input. In general, Symmetric therefore cannot be reduced to one constant ΔW.</p><p>The analytical Jacobian expressions were checked against PyTorch autograd in double precision. This structural distinction is not a causal claim about performance.</p><h2>Effective-rank analysis</h2>''' + table(["Rank", "LoRA effective update", "Symmetric local Jacobian"], [["1", "1.00", "1.00"], ["2", "1.92", "1.67"], ["4", "3.76", "3.09"], ["8", "6.57", "5.59"]], "Mean entropy effective rank across seeds") + table(["Rank", "U effective rank", "P effective rank", "Output-covariance effective rank"], [["1", "1.00", "1.00", "1.00"], ["2", "2.00", "1.98", "1.92"], ["4", "3.99", "3.89", "3.00"], ["8", "7.96", "7.28", "3.59"]], "Symmetric factor and output-covariance spectra") + '''<p>These quantities describe different mathematical objects and should not be interpreted as interchangeable notions of “weight rank”. In particular, the Symmetric local-Jacobian rank is not a direct analogue of a fixed LoRA weight-update rank.</p>''' + figure("publication/jacobian_effective_rank.svg", "Effective rank of the LoRA update and the Symmetric local Jacobian across nominal adapter ranks.", "<strong>Figure 7.</strong> Effective rank of the LoRA update and the Symmetric local Jacobian across nominal adapter ranks. The quantities are related measures of local transformation complexity, but they are not identical weight-space objects.") + '''<h2>Second-order structure</h2><p>For a fixed linear reduction of the adapter output by a vector <code>c</code>:</p><div class="formula">H = 2(α/r) U diag(Pc) Uᵀ</div><p>LoRA has an exactly zero adapter-only Hessian with respect to the adapter input because its branch is linear. Symmetric has an explicit second-order response. The analytical Hessian was checked against PyTorch autograd in double precision.</p>''' + table(["Rank", "Symmetric Hessian Frobenius norm"], [["1", "155.15"], ["2", "92.13"], ["4", "52.68"], ["8", "17.61"]], "Mean over seeds; LoRA is exactly zero") + '''<p>The decrease with nominal rank should not be interpreted as evidence that higher-rank adapters contain weaker or less useful interactions. Its magnitude depends on learned factors and on the α/r scaling used in the main protocol. Because the exact quadratic adapter has an input-independent Hessian for a fixed linear output reduction, repeated token activations are not independent Hessian observations. A full Transformer-block Hessian was not evaluated and is therefore not reported as an empirical result.</p>''' + figure("publication/adapter_interaction_hessian.svg", "Adapter-only second-order response of LoRA and the Symmetric Quadratic Adapter.", "<strong>Figure 8.</strong> Adapter-only second-order response of the Symmetric Quadratic Adapter. LoRA has zero adapter-only Hessian, whereas Symmetric has an explicit non-zero quadratic response. This structural distinction does not by itself establish a causal explanation for the observed performance differences.") + '''<h2>Computational cost at rank 4</h2><p>The matched benchmark uses batch size 1, sequence length 128, 10 warm-up iterations, and 30 measured iterations. Both methods use 6,144 trainable adapter parameters.</p>''' + table(["Method", "Forward latency", "Backward latency", "Peak VRAM", "Forward throughput"], [[x["method"], f'{float(x["forward_ms_mean"]):.3f} ± {float(x["forward_ms_sample_sd"]):.3f} ms', f'{float(x["backward_ms_mean"]):.3f} ± {float(x["backward_ms_sample_sd"]):.3f} ms', f'{float(x["peak_vram_mb"]):.2f} MiB', f'{float(x["tokens_per_second_forward"]):,.0f} tokens/s'] for x in cost], "Matched rank-4 benchmark") + '''<p>Relative to LoRA, Symmetric changes mean forward latency by approximately +0.22%, mean backward latency by −0.27%, peak allocated VRAM by +1.25 MiB, and forward throughput by approximately −0.22%. In this measured configuration, the two methods have nearly identical computational cost. The benchmark indicates that, in this implementation and hardware configuration, introducing the element-wise quadratic activation operation adds only a small measured computational overhead. This result should not be generalized to all hardware or model scales.</p></section>'''
    comparisons = '''<section class="hero compact"><p class="eyebrow">Project 01 · Comparisons</p><h1>Relationship to low-rank adaptation research</h1><p class="lede">The methods below are compared at the mathematical and architectural levels. Published benchmark results obtained with different backbones, datasets, training budgets, or evaluation protocols are not numerically ranked against the experiments in this study.</p></section><section>''' + table(["Method", "Core mechanism", "Relation to this study"], [["LoRA", "Low-rank linear correction <code>(α/r)(xA)B</code>", "Direct experimental baseline"], ["DoRA", "Decomposes weight magnitude and direction", "Different weight parameterization"], ["MoRA", "Uses a square trainable matrix with nonparametric transforms", "Weight-space method designed to increase effective update rank"], ["HiRA", "Hadamard-product high-rank update", "Weight-space higher-rank adaptation"], ["LoRAN", "Applies a nonlinear transformation to the low-rank weight update", "Nonlinear weight-space adaptation, not activation-space squaring"], ["PERA", "Polynomial expansion of low-rank factors", "Polynomial structure in parameter/factor space"], ["QuadraNet V2", "Factorized quadratic neural transformation", "Closely related verified quadratic-form precedent; full multi-output equivalence is not established"], ["This study", "<code>(α/r)((xU)⊙(xU))P</code> beside a frozen projection", "Activation-dependent symmetric quadratic correction"]], "Mathematical and architectural comparison; related methods were not experimental baselines") + '''<h2>PERA</h2><p>PERA introduces polynomial expansion in parameter and low-rank-factor space before factor composition. This study instead applies the nonlinearity directly to the projected activations: <code>x → xU → (xU)⊙(xU) → P</code>. Both approaches investigate higher-order structure in parameter-efficient adaptation, but the polynomial or quadratic operation acts on different mathematical objects.</p><p>PERA was not used as an experimental baseline in this project.</p><h2>QuadraNet V2</h2><p>For one output coordinate, <code>Δy_j = xQ_jxᵀ</code>, with <code>Q_j = (α/r)U diag(P[:,j])Uᵀ</code>. This places the method within the family of factorized quadratic transformations. Across a complete multi-output layer, all output coordinates share the projection directions contained in <code>U</code>, while <code>P</code> provides signed output-specific coefficients.</p><p>Consequently, similarity at the level of a single-output quadratic form does not establish complete architectural equivalence between the Symmetric adapter and QuadraNet V2. The present study therefore treats QuadraNet V2 as a closely related quadratic precedent rather than evidence of either exact equivalence or universal novelty.</p><h2>Position of the proposed method</h2><p>The main distinction of the Symmetric adapter is not simply that it uses low rank or that it introduces nonlinearity. Its defining feature is that the low-rank projection is applied to the incoming activation and the projected coordinates are squared before being mapped back to the output space.</p><p>This creates an activation-dependent quadratic correction with an input-dependent Jacobian, while retaining a parameter structure comparable in size to the matched LoRA branch.</p><p>The experiments in this project evaluate this specific design directly against LoRA under controlled parameter budgets. Other methods in this section are used to clarify the relationship to existing parameter-efficient and quadratic adaptation mechanisms, not as experimentally reproduced baselines.</p>''' + figure("figures/adapter-family-comparison.svg", "Architectural comparison of LoRA, Symmetric Quadratic Adaptation, PERA, and QuadraNet V2 showing where each higher-order operation is introduced.", "<strong>Figure 9.</strong> Architectural comparison of LoRA, Symmetric Quadratic Adaptation, PERA, and QuadraNet V2. The diagram highlights where the higher-order operation is introduced in each method; similar terminology or quadratic structure does not imply mathematical or architectural equivalence.") + '''</section>'''
    conclusions = '''<section class="hero compact"><p class="eyebrow">Project 01 · Conclusions</p><h1>What the evidence supports</h1></section><section><p>This study investigated whether a simple quadratic transformation in a low-dimensional activation space can provide a useful alternative to conventional linear low-rank adaptation. The results show that the Symmetric Quadratic Adapter is a practical and computationally lightweight mechanism for introducing explicit second-order interactions into a frozen Transformer, while retaining the same low-rank parameter structure used for comparison with LoRA.</p><p>The strongest evidence comes from the controlled WikiText-2 experiments. Across 24 independent 5,000-step runs, covering ranks 1, 2, 4, and 8 and three random seeds, Symmetric achieved lower mean final validation loss and lower mean held-out test loss than LoRA at every tested rank. The difference was largest at rank 8 in the final test evaluation, where mean loss decreased from 3.7319 ± 0.0035 for LoRA to 3.6938 ± 0.0044 for Symmetric. Importantly, the rank-1 convergence trajectories also show that the comparison depends on optimization time: LoRA initially performs better, while Symmetric overtakes it between the recorded 2,000- and 3,000-step checkpoints. These observations suggest that the behavior of quadratic adaptation cannot be characterized solely by its final parameter budget; rank and training duration also matter.</p><p>The scaling experiment provides an additional qualification. Holding the effective scale α/r constant changes the magnitude of the differences but preserves, for the tested seed, the qualitative pattern observed at 1,000 steps: LoRA performs better at rank 1, whereas Symmetric performs better at ranks 2, 4, and 8. This indicates that the observed rank trend is not explained exclusively by the changing α/r factor of the primary protocol, although the single-seed nature of this ablation prevents a broader conclusion.</p><p>The downstream AG News experiment provides an important counterexample to any claim of general superiority. Under the matched classification protocol, LoRA achieved higher mean accuracy and macro-F1 than Symmetric. Mean test accuracy was 0.8201 ± 0.0051 for LoRA and 0.8021 ± 0.0240 for Symmetric, with substantially greater variability for the quadratic adapter. The combined evidence therefore points to a task-dependent trade-off rather than a universally better adaptation mechanism.</p><p>The structural analyses help clarify why the two adapters are genuinely different. LoRA remains linear with respect to the adapter input and can be represented by a fixed low-rank weight update. Symmetric instead produces an input-dependent local Jacobian and possesses explicit non-zero adapter-level second derivatives. Its behavior therefore cannot, in general, be reduced to a single constant ΔW. Spectral measurements further show that the effective rank of the local Jacobian, the ranks of the learned factors, and the output-covariance rank describe distinct properties of the learned transformation and should not be interpreted as interchangeable notions of weight rank.</p><p>These additional expressive properties do not appear to introduce a substantial computational penalty in the measured configuration. At rank 4, forward latency and backward latency were almost identical to LoRA, while peak memory increased by only about 1.25 MiB. In this specific implementation, explicit quadratic activation interactions can therefore be introduced at approximately the same practical computational scale as the matched linear adapter.</p><p>Taken together, the results support a narrower but more useful conclusion than a claim of overall superiority: <strong>low-rank quadratic activation-space adaptation is a viable design point for parameter-efficient Transformer adaptation, and in the controlled WikiText-2 setting studied here it consistently improved final language-model loss relative to the matched LoRA baseline.</strong> At the same time, the AG News results demonstrate that this advantage does not automatically transfer across tasks.</p><p>The study also suggests that the functional form of a low-rank adapter matters in addition to its parameter count. Two adapters with matched trainable dimensions can induce substantially different local transformations: one linear and input independent, the other quadratic and activation dependent. This motivates treating adapter architecture—not only rank and parameter budget—as an experimental variable in parameter-efficient fine-tuning.</p><p>The current evidence remains limited to GPT-2 Small, a restricted set of adapter placements, two datasets, three seeds for the principal controlled experiments, and a single seed for the scaling ablation. The experiments therefore do not establish state-of-the-art performance, statistical significance across broad populations of runs, universal transfer to other Transformer families, or a causal relationship between second-order structure and improved language-model performance. Nor do they establish that quadratic low-rank adaptation itself is mathematically novel relative to the full prior literature.</p><p>The results instead establish a reproducible empirical starting point. Future work across larger models, additional tasks, broader placements, and independently replicated scaling configurations can determine whether the advantages observed here represent a broader property of activation-space quadratic adaptation or a characteristic of the specific regimes studied.</p><div class="callout good"><strong>Summary.</strong> Symmetric Quadratic Adaptation introduces explicit second-order interactions into a low-rank adapter with little measured computational overhead. In controlled GPT-2/WikiText-2 experiments it achieved lower final validation and held-out test loss than LoRA across ranks 1, 2, 4, and 8, while LoRA performed better on AG News classification. The evidence therefore supports Symmetric as a viable, task-dependent alternative to linear low-rank adaptation rather than a universally superior replacement.</div></section>'''
    reproducibility = '''<section class="hero compact"><p class="eyebrow">Project 01 · Reproducibility</p><h1>From evidence to figures</h1><p class="lede">Raw checkpoints stay private; sanitized per-seed tables, configurations, scripts, and provenance are tracked.</p></section><section><h2>Quick verification</h2><div class="formula">git clone https://github.com/xxlilloxx-cyber/federico-lolli-ai-research.git<br>cd federico-lolli-ai-research<br>python -m venv .venv &amp;&amp; . .venv/bin/activate<br>pip install -r requirements.txt<br>PYTEST_DISABLE_PLUGIN_AUTOLOAD=1 pytest -q<br>python scripts/validation/validate_public_long_data.py<br>python tools/build_public_site.py</div><p>Plot reproduction uses tracked CSVs and does not require model training. Training commands and private-output locations are documented in <a href="https://github.com/xxlilloxx-cyber/federico-lolli-ai-research/blob/main/research/reproducibility/REPRODUCIBILITY.md">REPRODUCIBILITY.md</a>.</p><h2>Canonical public data</h2><ul><li><a href="../../data/rank_5000_per_seed.csv">rank confirmation per seed</a></li><li><a href="../../data/downstream_controlled_results.csv">AG News per seed</a></li><li><a href="../../data/rank_scaling_ablation_aggregate.csv">scaling ablation</a></li><li><a href="../../data/jacobian_analysis.csv">Jacobian analysis</a></li><li><a href="../../data/computational_cost.csv">cost benchmark</a></li><li><a href="../../data/FIGURE_MANIFEST.csv">figure manifest</a></li></ul><p>Best validation, final validation, and final held-out test remain distinct. Test data did not select method, rank, hyperparameters, or checkpoint.</p></section>'''
    references = '''<section class="hero compact"><p class="eyebrow">Project 01 · References</p><h1>Verified original sources</h1><p class="lede">Related methods provide context and were not experimentally evaluated as baselines unless explicitly stated.</p></section><section><ol class="references"><li>Hu et al. (2022). <a href="https://openreview.net/forum?id=nZeVKeeFYf9">LoRA: Low-Rank Adaptation of Large Language Models</a>. ICLR.</li><li>Liu et al. (2024). <a href="https://proceedings.mlr.press/v235/liu24bn.html">DoRA: Weight-Decomposed Low-Rank Adaptation</a>. ICML.</li><li>Jiang et al. (2024). <a href="https://arxiv.org/abs/2405.12130">MoRA: High-Rank Updating for Parameter-Efficient Fine-Tuning</a>.</li><li>Huang et al. (2025). <a href="https://proceedings.iclr.cc/paper_files/paper/2025/hash/48c368f105e8145b945227b73255635a-Abstract-Conference.html">HiRA: Parameter-Efficient Hadamard High-Rank Adaptation</a>. ICLR.</li><li>Li, Song, and Hou (2024). <a href="https://aclanthology.org/2024.findings-emnlp.177/">LoRAN</a>. Findings of EMNLP.</li><li>Zhang et al. (2026). <a href="https://aclanthology.org/2026.findings-acl.650/">Polynomial Expansion Rank Adaptation</a>. Findings of ACL. DOI 10.18653/v1/2026.findings-acl.650.</li><li>Xu et al. (2026). <a href="https://openaccess.thecvf.com/content/WACV2026/html/Xu_QuadraNet_V2_Efficient_and_Sustainable_Training_of_High-Order_Neural_Networks_WACV_2026_paper.html">QuadraNet V2</a>. WACV.</li><li>Houlsby et al. (2019). <a href="https://proceedings.mlr.press/v97/houlsby19a.html">Parameter-Efficient Transfer Learning for NLP</a>. ICML.</li></ol><p>Full bibliographic metadata and equivalence qualifications are maintained in the repository’s <a href="https://github.com/xxlilloxx-cyber/federico-lolli-ai-research/tree/main/comparisons">comparisons directory</a>.</p></section>'''
    overview = overview.replace("../../data/SCIENTIFIC_MANUSCRIPT.md", "../../data/Federico_Lolli_Symmetric_Quadratic_Adaptation_GPT2.pdf")
    return {
        "index.html": shell("Symmetric Quadratic Adaptation for GPT-2 — Federico Lolli", "overview", overview, "Overview of Federico Lolli's controlled study of LoRA and activation-dependent Symmetric Quadratic adapters for frozen GPT-2."),
        "method.html": shell("Method — Symmetric Quadratic Adaptation", "method", method, "Mathematical formulation, dimensions, scaling, and GPT-2 insertion path for LoRA and the Symmetric Quadratic Adapter."),
        "experiments.html": shell("Experiments — Symmetric Quadratic Adaptation", "experiments", experiments, "Completed historical and controlled GPT-2 experiments on WikiText-2 and AG News, with protocols kept distinct."),
        "results.html": shell("Results — Symmetric Quadratic Adaptation", "results", results, "Controlled WikiText-2 and AG News results, rank confirmation, scaling ablation, seed variability, and convergence."),
        "mechanism.html": shell("Mechanism — Symmetric Quadratic Adaptation", "mechanism", mechanism, "Local Jacobian spectra, adapter-only Hessians, effective-rank measurements, and matched computational cost."),
        "comparisons.html": shell("Related Work — Symmetric Quadratic Adaptation", "comparisons", comparisons, "Mathematical and architectural comparison with LoRA, DoRA, MoRA, HiRA, LoRAN, PERA, and QuadraNet V2."),
        "conclusions.html": shell("Conclusions — Symmetric Quadratic Adaptation", "conclusions", conclusions, "Measured conclusions, mathematical properties, limitations, and unresolved questions from the controlled study."),
        "reproducibility.html": shell("Reproducibility — Symmetric Quadratic Adaptation", "reproducibility", reproducibility, "Validated commands, public data, configurations, provenance, and figure-generation resources for Project 01."),
        "references.html": shell("References — Symmetric Quadratic Adaptation", "references", references, "Verified original sources for LoRA-family methods, quadratic networks, GPT-2 adaptation, and related work."),
    }


